"use strict";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { BreadcrumbNavContainer, BreadcrumbNavLink } from "components/BreadcrumbNav";
import { LiquidityPositionInfo, LiquidityPositionInfoLoader } from "components/Liquidity/LiquidityPositionInfo";
import { useGetPoolTokenPercentage } from "components/Liquidity/hooks";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import { usePositionOwnerV2 } from "hooks/usePositionOwnerV2";
import { useV2Pair } from "hooks/useV2Pairs";
import NotFound from "pages/NotFound";
import { TextLoader } from "pages/Pool/Positions/shared";
import { useMemo } from "react";
import { ChevronRight } from "react-feather";
import { Helmet } from "react-helmet-async/lib/index";
import { Trans, useTranslation } from "react-i18next";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { setOpenModal } from "state/application/reducer";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { serializePositionInfo } from "utils/currencyAmountSerialization";
import { MultichainContextProvider } from "state/multichain/MultichainContext";
import { usePendingLPTransactionsChangeListener } from "state/transactions/hooks";
import { TransactionSettingsContextProvider } from "uniswap/src/features/transactions/settings/contexts/TransactionSettingsContext";
import { TransactionSettingKey } from "uniswap/src/features/transactions/settings/slice";
import { usePairAdder } from "state/user/hooks";
import { Button, Circle, Flex, Main, Shine, Text, styled } from "ui/src";
import { useV2Positions } from "hooks/useAbstractPositions";
import { useV2PositionFees } from "hooks/useV2PositionFees";
import { useV2PoolInfo } from "hooks/useV2PoolInfo";
import { StakingSection } from "components/Liquidity/StakingSection";
import { Token } from "@uniswap/sdk-core";
import { Pair } from "@uniswap/v2-sdk";
import { ethers } from "ethers";
import { useSupportedChainId } from "uniswap/src/features/chains/hooks/useSupportedChainId";
import { useLocalizationContext } from "uniswap/src/features/language/LocalizationContext";
import { ModalName } from "uniswap/src/features/telemetry/constants";
import { useUSDCValue } from "uniswap/src/features/transactions/hooks/useUSDCPrice";
import { shortenAddress } from "utilities/src/addresses";
import { NumberType } from "utilities/src/format/types";
import { useChainIdFromUrlParam } from "utils/chainParams";
import { useAccount } from "wagmi";
import { CurrencyAmount } from "@uniswap/sdk-core";
const BodyWrapper = styled(Main, {
  backgroundColor: "$surface1",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  width: "100%",
  maxWidth: 600,
  // intentionally less than the other LP screens
  zIndex: "$default",
  py: "$spacing24",
  px: "$spacing40",
  $lg: {
    px: "$padding20"
  }
});
function RowLoader({ withIcon }) {
  return <Flex row width="100%" justifyContent="space-between">
      <TextLoader variant="subheading2" width={120} />
      {withIcon ? <Flex row alignItems="center" gap="$gap4">
          <TextLoader variant="body2" width={78} />
          <Circle size={24} backgroundColor="$surface3" />
        </Flex> : <TextLoader variant="body2" width={72} />}
    </Flex>;
}
export default function V2PositionPageWrapper() {
  const chainId = useChainIdFromUrlParam();
  return <TransactionSettingsContextProvider settingKey={TransactionSettingKey.Swap}>
      <MultichainContextProvider initialChainId={chainId}>
        <V2PositionPage />
      </MultichainContextProvider>
    </TransactionSettingsContextProvider>;
}
function V2PositionPage() {
  const { pairAddress } = useParams();
  const chainId = useChainIdFromUrlParam();
  const account = useAccount();
  const supportedAccountChainId = useSupportedChainId(account.chainId);
  const { data: allV2Positions, isLoading: positionsLoading } = useV2Positions(chainId ?? supportedAccountChainId);
  const { data: poolInfo, isLoading: poolLoading } = useV2PoolInfo(pairAddress, chainId ?? supportedAccountChainId);
  const { data: positionFees, isLoading: feesLoading } = useV2PositionFees(pairAddress, chainId ?? supportedAccountChainId);
  const position = useMemo(() => {
    if (!pairAddress) return null;
    const userPosition = allV2Positions?.find(
      (pos) => pos.poolAddress.toLowerCase() === pairAddress.toLowerCase()
    );
    return userPosition || poolInfo;
  }, [allV2Positions, poolInfo, pairAddress]);
  const positionInfo = useMemo(() => {
    if (!position) return null;
    const walletBalance = parseFloat(ethers.utils.formatUnits(position.balance, 18));
    const stakedBalance = position.gaugeStakeAmount ? parseFloat(ethers.utils.formatUnits(position.gaugeStakeAmount, 18)) : 0;
    const totalUserBalance = walletBalance + stakedBalance;
    const totalSupply = parseFloat(position.totalSupply);
    const shareOfPool = totalSupply > 0 ? totalUserBalance / totalSupply : 0;
    const reserve0 = parseFloat(position.reserve0);
    const reserve1 = parseFloat(position.reserve1);
    const token0Amount = shareOfPool * reserve0;
    const token1Amount = shareOfPool * reserve1;
    const token0Decimals = parseInt(position.token0.decimals);
    const token1Decimals = parseInt(position.token1.decimals);
    const safeToken0Amount = Math.min(Math.max(token0Amount, 0), 1e6);
    const safeToken1Amount = Math.min(Math.max(token1Amount, 0), 1e6);
    const token0AmountFormatted = safeToken0Amount.toFixed(Math.min(token0Decimals, 6));
    const token1AmountFormatted = safeToken1Amount.toFixed(Math.min(token1Decimals, 6));
    const token0AmountWei = ethers.utils.parseUnits(token0AmountFormatted, token0Decimals).toString();
    const token1AmountWei = ethers.utils.parseUnits(token1AmountFormatted, token1Decimals).toString();
    const token0Object = new Token(
      chainId ?? supportedAccountChainId,
      position.token0.id,
      token0Decimals,
      position.token0.symbol,
      position.token0.name
    );
    const token1Object = new Token(
      chainId ?? supportedAccountChainId,
      position.token1.id,
      token1Decimals,
      position.token1.symbol,
      position.token1.name
    );
    const pairObject = new Pair(
      CurrencyAmount.fromRawAmount(token0Object, ethers.utils.parseUnits(position.reserve0, token0Decimals)),
      CurrencyAmount.fromRawAmount(token1Object, ethers.utils.parseUnits(position.reserve1, token1Decimals))
    );
    console.log("V2PositionPage - Calculated amounts:", {
      shareOfPool,
      token0Amount,
      token1Amount,
      safeToken0Amount,
      safeToken1Amount,
      token0AmountFormatted,
      token1AmountFormatted,
      token0AmountWei,
      token1AmountWei,
      walletBalance,
      stakedBalance,
      totalUserBalance,
      userBalance: position.balance,
      gaugeStakeAmount: position.gaugeStakeAmount,
      totalSupply: position.totalSupply,
      reserve0: position.reserve0,
      reserve1: position.reserve1
    });
    return {
      poolId: position.poolAddress,
      chainId: chainId ?? supportedAccountChainId,
      version: ProtocolVersion.V2,
      status: 1,
      // IN_RANGE
      isHidden: false,
      currency0Amount: CurrencyAmount.fromRawAmount(token0Object, token0AmountWei),
      currency1Amount: CurrencyAmount.fromRawAmount(token1Object, token1AmountWei),
      pair: pairObject,
      liquidityToken: new Token(
        chainId ?? supportedAccountChainId,
        position.poolAddress,
        18,
        `${position.token0.symbol}/${position.token1.symbol}`,
        `${position.token0.name}/${position.token1.name} LP`
      ),
      liquidityAmount: CurrencyAmount.fromRawAmount(
        new Token(
          chainId ?? supportedAccountChainId,
          position.poolAddress,
          18,
          `${position.token0.symbol}/${position.token1.symbol}`,
          `${position.token0.name}/${position.token1.name} LP`
        ),
        position.balance
      ),
      totalSupply: CurrencyAmount.fromRawAmount(
        new Token(
          chainId ?? supportedAccountChainId,
          position.poolAddress,
          18,
          `${position.token0.symbol}/${position.token1.symbol}`,
          `${position.token0.name}/${position.token1.name} LP`
        ),
        ethers.utils.parseUnits(position.totalSupply, 18).toString()
      ),
      poolType: position.stable ? "stable" : "volatile",
      // Add pool type from position data
      feeTier: void 0,
      // V2 doesn't use feeTier
      v4hook: void 0,
      owner: account?.address,
      // Set owner to current account
      // Add V2 fee information from dedicated hook
      token0UncollectedFees: positionFees?.token0UncollectedFees || "0",
      token1UncollectedFees: positionFees?.token1UncollectedFees || "0",
      // Add staking information from enhanced position data
      isStaked: position.isStaked || false,
      hasGaugeStake: position.hasGaugeStake || false,
      gaugeAddress: position.gaugeAddress,
      gaugeStakeAmount: position.gaugeStakeAmount
    };
  }, [position, chainId, supportedAccountChainId, account?.address, positionFees]);
  const feeValue0 = useMemo(() => {
    if (!positionInfo?.token0UncollectedFees || positionInfo.token0UncollectedFees === "0") return void 0;
    return CurrencyAmount.fromRawAmount(positionInfo.currency0Amount.currency, positionInfo.token0UncollectedFees);
  }, [positionInfo]);
  const feeValue1 = useMemo(() => {
    if (!positionInfo?.token1UncollectedFees || positionInfo.token1UncollectedFees === "0") return void 0;
    return CurrencyAmount.fromRawAmount(positionInfo.currency1Amount.currency, positionInfo.token1UncollectedFees);
  }, [positionInfo]);
  const hasFees = feeValue0?.greaterThan(0) || feeValue1?.greaterThan(0) || false;
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const { formatCurrencyAmount, formatPercent } = useLocalizationContext();
  const { t } = useTranslation();
  const savedSerializedPairs = useAppSelector(({ user: { pairs } }) => pairs);
  const [, pair] = useV2Pair(
    positionInfo?.currency0Amount.currency,
    positionInfo?.currency1Amount.currency,
    positionInfo?.poolType === "stable"
  );
  const addPair = usePairAdder();
  usePendingLPTransactionsChangeListener(() => {
  });
  const { currency0Amount, currency1Amount, liquidityAmount } = positionInfo ?? {};
  const token0USDValue = useUSDCValue(currency0Amount);
  const token1USDValue = useUSDCValue(currency1Amount);
  const poolTokenPercentage = useGetPoolTokenPercentage(positionInfo);
  const liquidityTokenAddress = positionInfo?.liquidityToken?.isToken ? positionInfo.liquidityToken.address : void 0;
  const isOwner = usePositionOwnerV2(account?.address, liquidityTokenAddress, positionInfo?.chainId);
  const isLoading = positionsLoading || poolLoading || feesLoading;
  if (!isLoading && (!positionInfo || (!currency0Amount || !currency1Amount))) {
    return <NotFound
      title={<Text variant="heading2">{t("position.notFound")}</Text>}
      subtitle={<Flex centered maxWidth="75%" mt="$spacing20">
            <Text color="$neutral2" variant="heading3" textAlign="center">
              {t("position.notFound.description")}
            </Text>
          </Flex>}
      actionButton={<Flex row centered>
            <Button width="fit-content" variant="branded" onPress={() => navigate("/positions")}>
              {t("common.backToPositions")}
            </Button>
          </Flex>}
    />;
  }
  return <>
      <Helmet>
        <title>
          {t(`liquidityPool.positions.page.title`, {
    quoteSymbol: currency1Amount?.currency.symbol,
    baseSymbol: currency0Amount?.currency.symbol
  })}
        </title>
      </Helmet>
      <BodyWrapper>
        <Flex gap="$gap20" width="100%">
          <Flex row width="100%" justifyContent="flex-start" alignItems="center">
            <BreadcrumbNavContainer aria-label="breadcrumb-nav">
              <BreadcrumbNavLink to="/liquidity">
                <Trans i18nKey="pool.positions.title" /> <ChevronRight size={14} />
              </BreadcrumbNavLink>
              {positionInfo && <Text variant="subheading2">{shortenAddress(positionInfo.poolId)}</Text>}
            </BreadcrumbNavContainer>
          </Flex>

          {isLoading || !positionInfo ? <Shine>
              <LiquidityPositionInfoLoader hideStatus />
            </Shine> : <LiquidityPositionInfo positionInfo={positionInfo} />}
          {isOwner && <Flex row gap="$gap12" alignItems="center" maxWidth="100%" flexWrap="wrap">
              <Button
    size="small"
    emphasis="secondary"
    $sm={{ width: "100%" }}
    isDisabled={isLoading}
    onPress={() => {
      dispatch(setOpenModal({ name: ModalName.AddLiquidity, initialState: serializePositionInfo(positionInfo) }));
    }}
  >
                {t("common.addLiquidity")}
              </Button>
              <Button
    size="small"
    $sm={{ width: "100%" }}
    isDisabled={isLoading}
    onPress={() => {
      dispatch(setOpenModal({ name: ModalName.RemoveLiquidity, initialState: serializePositionInfo(positionInfo) }));
    }}
  >
                {t("pool.removeLiquidity")}
              </Button>
              {hasFees && <Button
    size="small"
    maxWidth="fit-content"
    fill={false}
    isDisabled={isLoading}
    onPress={() => {
      if (hasFees && positionInfo) {
        dispatch(
          setOpenModal({
            name: ModalName.ClaimFee,
            initialState: serializePositionInfo(positionInfo)
          })
        );
      }
    }}
  >
                  {t("pool.collectFees")}
                </Button>}
            </Flex>}
          <Flex borderColor="$surface3" borderWidth="$spacing1" p="$spacing24" gap="$gap12" borderRadius="$rounded20">
            {isLoading || !currency0Amount || !currency1Amount ? <Shine>
                <Flex gap="$gap12">
                  <RowLoader />
                  <RowLoader withIcon />
                  <RowLoader withIcon />
                  <RowLoader withIcon />
                  <RowLoader />
                </Flex>
              </Shine> : <>
                <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    <Trans i18nKey="position.currentValue" />
                  </Text>
                  <Text variant="body2">
                    {token0USDValue && token1USDValue ? formatCurrencyAmount({
    value: token0USDValue.add(token1USDValue),
    type: NumberType.FiatStandard
  }) : "-"}
                  </Text>
                </Flex>
                <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    <Trans i18nKey="pool.totalTokens" />
                  </Text>
                  <Flex row gap="$gap8">
                    <Text variant="body2">
                      {formatCurrencyAmount({ value: liquidityAmount, type: NumberType.TokenNonTx })}
                    </Text>
                    <DoubleCurrencyLogo currencies={[currency0Amount?.currency, currency1Amount?.currency]} size={24} />
                  </Flex>
                </Flex>
                <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    <Trans
    i18nKey="position.depositedCurrency"
    values={{ currencySymbol: currency0Amount.currency.symbol }}
  />
                  </Text>
                  <Flex row gap="$gap8">
                    <Text variant="body2">
                      {formatCurrencyAmount({ value: currency0Amount, type: NumberType.TokenNonTx })}
                    </Text>
                    <DoubleCurrencyLogo currencies={[currency0Amount?.currency]} size={24} />
                  </Flex>
                </Flex>
                <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    <Trans
    i18nKey="position.depositedCurrency"
    values={{ currencySymbol: currency1Amount.currency.symbol }}
  />
                  </Text>
                  <Flex row gap="$gap8">
                    <Text variant="body2">
                      {formatCurrencyAmount({ value: currency1Amount, type: NumberType.TokenNonTx })}
                    </Text>
                    <DoubleCurrencyLogo currencies={[currency1Amount?.currency]} size={24} />
                  </Flex>
                </Flex>
                <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    <Trans i18nKey="addLiquidity.shareOfPool" />
                  </Text>
                  <Text variant="body2">{formatPercent(poolTokenPercentage?.toSignificant(6))}</Text>
                </Flex>
              </>}
          </Flex>
          
          {
    /* Uncollected Fees Section */
  }
          {hasFees && <Flex borderColor="$surface3" borderWidth="$spacing1" p="$spacing24" gap="$gap12" borderRadius="$rounded20">
              <Flex row width="100%" justifyContent="space-between" alignItems="center">
                <Text variant="subheading2" color="$neutral2">
                  <Trans i18nKey="pool.uncollectedFees" />
                </Text>
                <Button
    size="xsmall"
    emphasis="primary"
    isDisabled={isLoading}
    onPress={() => {
      if (hasFees && positionInfo) {
        dispatch(
          setOpenModal({
            name: ModalName.ClaimFee,
            initialState: serializePositionInfo(positionInfo)
          })
        );
      }
    }}
  >
                  <Trans i18nKey="pool.collectFees" />
                </Button>
              </Flex>
              
              {feeValue0 && feeValue0.greaterThan(0) && <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    {feeValue0.currency.symbol} <Trans i18nKey="common.fees" />
                  </Text>
                  <Text variant="body2">
                    {formatCurrencyAmount({ value: feeValue0, type: NumberType.TokenNonTx })}
                  </Text>
                </Flex>}
              
              {feeValue1 && feeValue1.greaterThan(0) && <Flex row width="100%" justifyContent="space-between">
                  <Text variant="subheading2" color="$neutral2">
                    {feeValue1.currency.symbol} <Trans i18nKey="common.fees" />
                  </Text>
                  <Text variant="body2">
                    {formatCurrencyAmount({ value: feeValue1, type: NumberType.TokenNonTx })}
                  </Text>
                </Flex>}
            </Flex>}
          
          {
    /* Staking Section */
  }
          {positionInfo && <StakingSection position={positionInfo} />}
        </Flex>
      </BodyWrapper>
    </>;
}
