"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { ethers } from "ethers";
const POOL_ABI = [
  {
    inputs: [],
    name: "index0",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [],
    name: "index1",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ name: "", type: "address" }],
    name: "supplyIndex0",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ name: "", type: "address" }],
    name: "supplyIndex1",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ name: "", type: "address" }],
    name: "claimable0",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  },
  {
    inputs: [{ name: "", type: "address" }],
    name: "claimable1",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const ERC20_ABI = [
  {
    inputs: [{ name: "account", type: "address" }],
    name: "balanceOf",
    outputs: [{ name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const MULTICALL3_ABI = [
  {
    inputs: [
      {
        components: [
          { name: "target", type: "address" },
          { name: "callData", type: "bytes" }
        ],
        name: "calls",
        type: "tuple[]"
      }
    ],
    name: "aggregate",
    outputs: [
      { name: "blockNumber", type: "uint256" },
      { name: "returnData", type: "bytes[]" }
    ],
    stateMutability: "payable",
    type: "function"
  }
];
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
export function useV2PositionFees(poolAddress, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  return useQuery({
    queryKey: ["v2-position-fees", poolAddress, account.address, chainId],
    queryFn: async () => {
      if (!poolAddress || !account.address || !provider) {
        return null;
      }
      try {
        const multicallContract = new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
        const poolContract = new Contract(poolAddress, POOL_ABI, provider);
        const lpTokenContract = new Contract(poolAddress, ERC20_ABI, provider);
        const calls = [
          // Pool global indices
          {
            target: poolAddress,
            callData: poolContract.interface.encodeFunctionData("index0")
          },
          {
            target: poolAddress,
            callData: poolContract.interface.encodeFunctionData("index1")
          },
          // User indices
          {
            target: poolAddress,
            callData: poolContract.interface.encodeFunctionData("supplyIndex0", [account.address])
          },
          {
            target: poolAddress,
            callData: poolContract.interface.encodeFunctionData("supplyIndex1", [account.address])
          },
          // Already claimable amounts
          {
            target: poolAddress,
            callData: poolContract.interface.encodeFunctionData("claimable0", [account.address])
          },
          {
            target: poolAddress,
            callData: poolContract.interface.encodeFunctionData("claimable1", [account.address])
          },
          // User LP balance
          {
            target: poolAddress,
            callData: lpTokenContract.interface.encodeFunctionData("balanceOf", [account.address])
          }
        ];
        const [, results] = await multicallContract.callStatic.aggregate(calls);
        const globalIndex0 = poolContract.interface.decodeFunctionResult("index0", results[0])[0];
        const globalIndex1 = poolContract.interface.decodeFunctionResult("index1", results[1])[0];
        const userIndex0 = poolContract.interface.decodeFunctionResult("supplyIndex0", results[2])[0];
        const userIndex1 = poolContract.interface.decodeFunctionResult("supplyIndex1", results[3])[0];
        const alreadyClaimable0 = poolContract.interface.decodeFunctionResult("claimable0", results[4])[0];
        const alreadyClaimable1 = poolContract.interface.decodeFunctionResult("claimable1", results[5])[0];
        const balance = lpTokenContract.interface.decodeFunctionResult("balanceOf", results[6])[0];
        const indexDelta0 = globalIndex0.sub(userIndex0);
        const indexDelta1 = globalIndex1.sub(userIndex1);
        const WEI_PER_ETHER = ethers.constants.WeiPerEther;
        const newlyAccrued0 = balance.mul(indexDelta0).div(WEI_PER_ETHER);
        const newlyAccrued1 = balance.mul(indexDelta1).div(WEI_PER_ETHER);
        const totalClaimable0 = alreadyClaimable0.add(newlyAccrued0);
        const totalClaimable1 = alreadyClaimable1.add(newlyAccrued1);
        console.log("\u{1F522} [V2 POSITION FEES] Calculated fees for individual position:", {
          poolAddress,
          user: account.address,
          globalIndex0: globalIndex0.toString(),
          globalIndex1: globalIndex1.toString(),
          userIndex0: userIndex0.toString(),
          userIndex1: userIndex1.toString(),
          indexDelta0: indexDelta0.toString(),
          indexDelta1: indexDelta1.toString(),
          balance: balance.toString(),
          alreadyClaimable0: alreadyClaimable0.toString(),
          alreadyClaimable1: alreadyClaimable1.toString(),
          newlyAccrued0: newlyAccrued0.toString(),
          newlyAccrued1: newlyAccrued1.toString(),
          totalClaimable0: totalClaimable0.toString(),
          totalClaimable1: totalClaimable1.toString()
        });
        return {
          token0UncollectedFees: totalClaimable0.toString(),
          token1UncollectedFees: totalClaimable1.toString(),
          hasClaimableFees: totalClaimable0.gt(0) || totalClaimable1.gt(0)
        };
      } catch (error) {
        console.error("Failed to calculate V2 position fees:", error);
        throw error;
      }
    },
    enabled: !!poolAddress && !!account.address && !!provider,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
