"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { BigNumber } from "@ethersproject/bignumber";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useUserGaugeData } from "./useGaugeData";
const V2_PAIR_ABI = [
  {
    constant: true,
    inputs: [],
    name: "token0",
    outputs: [{ name: "", type: "address" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "token1",
    outputs: [{ name: "", type: "address" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "getReserves",
    outputs: [
      { name: "reserve0", type: "uint112" },
      { name: "reserve1", type: "uint112" },
      { name: "blockTimestampLast", type: "uint32" }
    ],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "totalSupply",
    outputs: [{ name: "", type: "uint256" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [{ name: "", type: "address" }],
    name: "balanceOf",
    outputs: [{ name: "", type: "uint256" }],
    type: "function"
  }
];
const TOKEN_ABI = [
  {
    constant: true,
    inputs: [],
    name: "symbol",
    outputs: [{ name: "", type: "string" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "name",
    outputs: [{ name: "", type: "string" }],
    type: "function"
  },
  {
    constant: true,
    inputs: [],
    name: "decimals",
    outputs: [{ name: "", type: "uint8" }],
    type: "function"
  }
];
export function useV2PoolInfo(poolAddress, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const { data: userGaugeData, isLoading: isLoadingGaugeData } = useUserGaugeData();
  return useQuery({
    queryKey: ["v2-pool-info", poolAddress, account.address, chainId, userGaugeData?.stakes?.length],
    queryFn: async () => {
      if (!poolAddress || !provider) return null;
      try {
        const pairContract = new Contract(poolAddress, V2_PAIR_ABI, provider);
        const [
          token0Address,
          token1Address,
          reserves,
          totalSupply,
          userBalance
        ] = await Promise.all([
          pairContract.token0(),
          pairContract.token1(),
          pairContract.getReserves(),
          pairContract.totalSupply(),
          account.address ? pairContract.balanceOf(account.address) : BigNumber.from(0)
        ]);
        const token0Contract = new Contract(token0Address, TOKEN_ABI, provider);
        const token1Contract = new Contract(token1Address, TOKEN_ABI, provider);
        const [
          token0Symbol,
          token0Name,
          token0Decimals,
          token1Symbol,
          token1Name,
          token1Decimals
        ] = await Promise.all([
          token0Contract.symbol(),
          token0Contract.name(),
          token0Contract.decimals(),
          token1Contract.symbol(),
          token1Contract.name(),
          token1Contract.decimals()
        ]);
        let isStaked = false;
        let hasGaugeStake = false;
        let gaugeAddress;
        let gaugeStakeAmount;
        if (userGaugeData?.stakes && poolAddress) {
          const stake = userGaugeData.stakes.find(
            (stake2) => stake2.gauge.pool.toLowerCase() === poolAddress.toLowerCase()
          );
          if (stake) {
            hasGaugeStake = true;
            gaugeAddress = stake.gauge.id;
            gaugeStakeAmount = stake.amount;
            isStaked = BigNumber.from(stake.amount || "0").gt(0);
          }
        }
        const position = {
          type: "v2",
          poolAddress,
          token0: {
            id: token0Address.toLowerCase(),
            symbol: token0Symbol,
            name: token0Name,
            decimals: token0Decimals.toString()
          },
          token1: {
            id: token1Address.toLowerCase(),
            symbol: token1Symbol,
            name: token1Name,
            decimals: token1Decimals.toString()
          },
          balance: userBalance.toString(),
          totalSupply: totalSupply.toString(),
          reserve0: reserves.reserve0.toString(),
          reserve1: reserves.reserve1.toString(),
          reserveUSD: "0",
          // Would need price data to calculate
          stable: false,
          // Abstract DEX V2 pools are all volatile
          // Add staking data
          isStaked,
          hasGaugeStake,
          gaugeAddress,
          gaugeStakeAmount
        };
        return position;
      } catch (error) {
        console.error("Failed to fetch V2 pool info:", error);
        return null;
      }
    },
    enabled: !!poolAddress && !!provider && !isLoadingGaugeData,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
